Notation SEGS := asegs (only parsing).
Local Ltac xms H := first [exact H | apply msteps_bridge; exact H].

Definition AVSNPRINTF_STUB : Z := 0xa3a80.
Definition IVS_PFC_RA : Z := 0xa8824.
Definition IVS_REAL_RA : Z := 0xa8840.
Definition IVS_RETPC : Z := 0xa88d4.

