Section Ivsn.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Variables (F : bvmap 5 word) (fc : bv 32).
  Variable gd : Z.
  Hypothesis Hgd : 0 <= gd < 2 ^ 64.
  Variables (R : bvmap 5 word) (M : mem) (u ret v conv lo shi : Z).
  Hypothesis Hra : getr R 1%bv = Z_to_bv 64 ret.
  Hypothesis Hret : ret_ok (Z_to_bv 64 ret).
  Hypothesis Hretr : 0 <= ret < 2 ^ 64.
  Hypothesis Hsp : getr R 2%bv = Z_to_bv 64 u.
  Hypothesis Ha0 : getr R 10%bv = Z_to_bv 64 (u + 152).
  Hypothesis Ha1 : getr R 11%bv = Z_to_bv 64 24.
  Hypothesis Ha2 : getr R 12%bv = Z_to_bv 64 (u + 176).
  Hypothesis Ha3 : getr R 13%bv = Z_to_bv 64 (u + 48).
  Hypothesis Hulo : 2 ^ 33 <= u - 4784.
  Hypothesis Huhi : u + 180 < 2 ^ 47.
  Hypothesis Hal : u mod 16 = 0.
  Hypothesis HD : mdef M (u - 4784) 4964.
  Hypothesis Fv : fld SEGS M (u + 48) 8 v.
  Hypothesis Hv : 0 <= v < 2 ^ 64.
  Hypothesis F0 : fld SEGS M (u + 176) 1 37.
  Hypothesis F1 : fld SEGS M (u + 177) 1 108.
  Hypothesis F2 : fld SEGS M (u + 178) 1 conv.
  Hypothesis F3 : fld SEGS M (u + 179) 1 0.
  Hypothesis Hconv : conv = 117 \/ conv = 100 \/ conv = 120.
  Hypothesis Hvpos : conv = 100 -> v < 2 ^ 63.
  Hypothesis FCAN : fld SEGS M A_CANARY 8 gd.

  Hypothesis RF : rfull R.
  Hypothesis NI : ninv lo shi M.
  Hypothesis STK : stk asegs M lo u.
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LOS : lo + AINTRIN_STACK + 3552 <= u.
  Hypothesis SHI : u + 244 <= shi.

  Definition ivs_post (nc : Z) (R' : bvmap 5 word) (M' : mem) : Prop :=
    getr R' 10%bv = Z_to_bv 64 nc /\ 1 <= nc <= 21
    /\ (forall r, In r leaf_kept -> getr R' r = getr R r)
    /\ stores_in (fun a => zwin (u - 3488 - AINTRIN_STACK) u a \/ zwin (u + 152) (u + 152 + nc + 1) a) M M'
    /\ rfull R' /\ ninv lo shi M' /\ stk asegs M' lo u.

  Lemma vsnprintf_icpt : exists nc R' M',
    HExec.msteps SEGS (@mkst (PropExec.mkFP F fc) R (Z_to_bv 64 AVSNPRINTF_STUB) M (seg_rom SEGS)) (@mkst (PropExec.mkFP F fc) R' (Z_to_bv 64 ret) M' (seg_rom SEGS))
    /\ ivs_post nc R' M'.
Proof.
